            ["Pick coordinates all use it. Change it later with BPGMAPCS."] = "تستخدمه كل أوامر قراءة الإحداثيات. يمكنك تغييره لاحقًا بالأمر BPGMAPCS.",["Select a system in the list first."] = "اختر نظامًا من القائمة أولًا.",
            ["B+ CAD Tools - Set on the drawing?"] = "B+ CAD Tools - هل يُضبط على الرسم؟",["Also move the objects (needs a known current system: none found)"] = "تحريك العناصر أيضًا (يتطلب نظامًا حاليًا معروفًا: لم يُعثر على أي نظام)",
            ["Off (default): nothing is moved."] = "متوقف (الافتراضي): لا يُحرَّك شيء.",["That entry could not be opened."] = "تعذّر فتح هذا الإدخال.",
            ["This system is not in your Autodesk library, so it cannot be set on the drawing. B+ tools still use it."] = "هذا النظام غير موجود في مكتبة أوتودسك لديك، لذا لا يمكن ضبطه على الرسم. تستمر أدوات B+ في استخدامه.",
            ["Closest match, NOT identical (datum or parameters may differ). Setting it declares the drawing to be in THIS system."] = "أقرب تطابق وليس مطابقًا (قد يختلف المرجع أو المعاملات). ضبطه يعني أن الرسم في هذا النظام.",
            ["Treat WGS 84 / UTM as identical to within about 1 m."] = "اعتبر WGS 84 / UTM متطابقين بفارق نحو 1 م.",
            // convert points
            ["This Civil 3D version has no CogoPoints.Add(point, bool)."] = "هذا الإصدار من Civil 3D لا يحتوي الدالة CogoPoints.Add(point, bool).",["Cannot set the point number in this Civil 3D version."] = "لا يمكن ضبط رقم النقطة في هذا الإصدار من Civil 3D.",
            ["A number that is already used is never changed: that point is skipped and listed."] = "الرقم المستخدم لا يُغيَّر أبدًا: تُتخطى تلك النقطة وتُدرج في القائمة.",
            ["Next you select the points. You see a summary before anything changes, and one UNDO reverses it."] = "بعد ذلك تحدد النقاط. يظهر لك ملخص قبل أي تغيير، وأمر UNDO واحد يتراجع عنه.",
            ["The start number must be a whole number, 1 or more."] = "يجب أن يكون رقم البداية عددًا صحيحًا لا يقل عن 1.",
            ["Convert points needs Civil 3D. Nothing changed."] = "تحويل النقاط يتطلب Civil 3D. لم يتغير شيء.",["Select the AutoCAD points to convert: "] = "حدّد نقاط أوتوكاد المراد تحويلها: ",["Select the COGO points to convert: "] = "حدّد نقاط COGO المراد تحويلها: ",
            ["Will convert: "] = "سيتم تحويل: ",["Skipped, number already used: "] = "متخطاة، الرقم مستخدم: ",["Skipped, no number: "] = "متخطاة، بلا رقم: ",["Originals stay in the drawing."] = "تبقى الأصول في الرسم.",
            ["Originals are deleted after conversion (UNDO brings them back)."] = "تُحذف الأصول بعد التحويل (يعيدها UNDO).",
            // tools
            ["Click a row. Ctrl+click or Shift+click for more rows. Ctrl+A selects all."] = "انقر صفًا. استخدم Ctrl+نقر أو Shift+نقر لتحديد صفوف أكثر. Ctrl+A يحدد الكل.",
            ["Pasted as tab-separated text: it opens in Excel or Notepad as columns. Ctrl+C copies the selected rows."] = "يُنسخ كنص مفصول بعلامات جدولة: يُفتح في Excel أو المفكرة على هيئة أعمدة. Ctrl+C ينسخ الصفوف المحددة.",
            ["No row is selected. Click a row first, or use Copy all rows."] = "لم يُحدَّد أي صف. انقر صفًا أولًا أو استخدم نسخ كل الصفوف.",["Nothing to copy: none of those rows is closed, so there is no area."] = "لا شيء للنسخ: لا يوجد بينها خط مغلق، فلا توجد مساحة.",
            ["Click a row first."] = "انقر صفًا أولًا.",["Length (m)  (shapes)"] = "الطول (م)  (الأشكال)",["Coordinates (E, N)  (points)"] = "الإحداثيات (E, N)  (النقاط)",["Add Z (elevation)"] = "إضافة Z (المنسوب)",["Centre of the shape (closed ones)"] = "مركز الشكل (للأشكال المغلقة)",
            ["Points: the leader starts at the point. Shapes ignore the coordinate choice."] = "النقاط: يبدأ خط الإشارة من النقطة. الأشكال تتجاهل خيار الإحداثيات.",
            ["Each leader goes up and right by 3 x the text height, on layer BP-LEADER. One UNDO."] = "كل خط إشارة يمتد إلى الأعلى واليمين بمقدار 3 أمثال ارتفاع النص، على الطبقة BP-LEADER. أمر UNDO واحد.",
            ["Text height must be a number above zero."] = "يجب أن يكون ارتفاع النص رقمًا أكبر من صفر.",["Hybrid (satellite with labels)"] = "هجين (أقمار صناعية مع الأسماء)",["Satellite"] = "أقمار صناعية",["Roadmap"] = "خريطة طرق",
            ["Coordinate system..."] = "نظام الإحداثيات...",["Google key..."] = "مفتاح Google...",["Changes to map type and opacity apply when you press OK."] = "تُطبَّق تغييرات نوع الخريطة والشفافية عند الضغط على موافق.",
            ["Table insertion point (top left): "] = "نقطة إدراج الجدول (أعلى اليسار): ",["First point number <1>: "] = "رقم النقطة الأولى <1>: ",
            ["This drawing has no coordinate system yet. Pick one (Live map > Options > Coordinate system) and run the command again."] = "لا يوجد نظام إحداثيات لهذا الرسم بعد. اختر نظامًا (الخريطة الحية > خيارات > نظام الإحداثيات) ثم أعد تشغيل الأمر.",
            ["No coordinate records were found in this file."] = "لم يُعثر على سجلات إحداثيات في هذا الملف.",
            // survey import/export
            ["Custom order..."] = "ترتيب مخصص...",["Points file (txt, csv or xlsx):"] = "ملف النقاط (txt أو csv أو xlsx):",["Column order:"] = "ترتيب الأعمدة:",["Add text labels (number and code)"] = "إضافة كتابة نصية (الرقم والكود)",["Text height:"] = "ارتفاع النص:",
            ["Choose a file to see a preview."] = "اختر ملفًا لعرض معاينة.",["Column order must use P, E, N, Z, D once each (for example PENZD)."] = "يجب أن يستخدم ترتيب الأعمدة الأحرف P وE وN وZ وD مرة واحدة لكل منها (مثل PENZD).",
            ["Comma (csv)"] = "فاصلة (csv)",["Categories to export:"] = "الفئات المراد تصديرها:",["Save as..."] = "حفظ باسم...",["The file is UTF-8, one point per line, no hidden characters."] = "الملف بترميز UTF-8، نقطة واحدة في كل سطر، بلا محارف مخفية.",
            ["Choose where to save the file."] = "اختر مكان حفظ الملف.",["Tick at least one category."] = "علّم فئة واحدة على الأقل.",["Add at least one category."] = "أضف فئة واحدة على الأقل.",["Tick the categories to show:"] = "علّم الفئات المراد إظهارها:",
            ["Separate lines when the code carries a number (RD1 and RD2 are two lines)"] = "خطوط منفصلة عندما يحمل الكود رقمًا (RD1 وRD2 خطان)",["Only these codes (empty = all coded points), e.g. RD, EG:"] = "هذه الأكواد فقط (فارغ = كل النقاط ذات الأكواد)، مثل RD, EG:",
            ["Add the word CLOSE to a point's description to close that line."] = "أضف كلمة CLOSE إلى وصف النقطة لإغلاق ذلك الخط.",["Lines are 3D polylines on layers BP-LINE-<code>. One UNDO removes them."] = "الخطوط عبارة عن خطوط متعددة ثلاثية الأبعاد على الطبقات BP-LINE-<الكود>. أمر UNDO واحد يزيلها.",
            ["Zoom to centres on the point and marks it with a red circle. Select in drawing selects the points of that finding."] = "التكبير إلى يركّز على النقطة ويعلّمها بدائرة حمراء. التحديد في الرسم يحدد نقاط تلك النتيجة.",
            ["Select points (Enter for all points)"] = "حدّد النقاط (Enter لكل النقاط)",["First point (Enter to finish): "] = "النقطة الأولى (Enter للإنهاء): ",["Second point: "] = "النقطة الثانية: ",["Slope distance (with Z)"] = "المسافة المائلة (مع Z)",["Height difference (dZ)"] = "فرق الارتفاع (dZ)",
            ["Writing in the drawing adds a line and the horizontal distance on layer BP-MEASURE. Close, then pick the next pair (Enter ends)."] = "الكتابة في الرسم تضيف خطًا والمسافة الأفقية على الطبقة BP-MEASURE. أغلق ثم حدد الزوج التالي (Enter للإنهاء).",
            ["Place an area label for each? [Yes/No] <No>: "] = "هل تضع كتابة مساحة لكل منها؟ [Yes/No] <No>: ",["Pick point A (from): "] = "حدّد النقطة A (من): ",["Pick point B (to): "] = "حدّد النقطة B (إلى): ",
            ["From point A to point B  (take distance and level difference)"] = "من النقطة A إلى النقطة B  (أخذ المسافة وفرق المنسوب)",["You pick A, then B in the drawing. The selection moves by B minus A."] = "تحدد A ثم B في الرسم. يتحرك المحدد بمقدار B ناقص A.",["Typed offsets (used only in the first mode)"] = "إزاحات مكتوبة (تُستخدم في الوضع الأول فقط)",["Type the offsets"] = "اكتب الإزاحات",
            // clean
            ["FOUND (nothing is changed yet)"] = "الموجود (لم يتغير شيء بعد)",["Empty layers (no objects)"] = "الطبقات الفارغة (بلا عناصر)",["Exact duplicate objects (same type, layer and place)"] = "العناصر المكررة تمامًا (النوع والطبقة والموضع نفسها)",
            ["Hidden or frozen layers that hold objects (shown only)"] = "الطبقات المخفية أو المجمّدة التي تحتوي عناصر (للعرض فقط)",
            ["Layers that hold objects are never deleted. Layer 0, Defpoints, the current layer and xref layers are skipped. Duplicates are off until you tick them."] = "الطبقات التي تحتوي عناصر لا تُحذف أبدًا. تُتخطى الطبقة 0 وDefpoints والطبقة الحالية وطبقات المراجع الخارجية. المكررات متوقفة حتى تعلّمها.",
            ["Save a backup first: "] = "حفظ نسخة احتياطية أولًا: ",["Save the drawing first, then run Clean drawing."] = "احفظ الرسم أولًا ثم شغّل تنظيف الرسم.",
            ["This drawing has unsaved changes. Save it first so the backup and the size comparison are correct?"] = "في هذا الرسم تغييرات غير محفوظة. هل تحفظه أولًا ليكون النسخ الاحتياطي ومقارنة الحجم صحيحين؟",
            // join and trim
            ["Only join ends that already touch (tolerance 0.001 m)"] = "دمج الأطراف الملامسة فقط (السماحية 0.001 م)",
            ["If the extended lines do not cross within the gap distance (or an end is an arc), that gap is joined straight across."] = "إذا لم يتقاطع امتداد الخطين ضمن مسافة الفجوة (أو كان أحد الطرفين قوسًا)، تُوصل الفجوة بخط مستقيم.",
            ["Keep the original shapes (default: they are replaced)"] = "الإبقاء على الأشكال الأصلية (الافتراضي: تُستبدل)",["Result of the check (before anything is changed)"] = "نتيجة الفحص (قبل تغيير أي شيء)",
            ["Type the gap as a number."] = "اكتب الفجوة رقمًا.",["The gap must be a number, zero or more."] = "يجب أن تكون الفجوة رقمًا لا يقل عن صفر.",
            ["Lines, polylines, arcs, circles (cut at the boundary)"] = "الخطوط والخطوط المتعددة والأقواس والدوائر (تُقص عند الحدود)",["Points and text (removed when on the wrong side)"] = "النقاط والنصوص (تُحذف إذا كانت في الجهة الخطأ)",
            ["Blocks (kept whole if the insertion point is on the kept side)"] = "الكتل (تبقى كاملة إذا كانت نقطة إدراجها في الجهة المحتفَظ بها)",["Hatches are not trimmed in this version: they stay as they are."] = "لا يُقص التهشير في هذا الإصدار: يبقى كما هو.",
            ["Keep inside: only objects that cross the boundary are cut. Nothing outside is touched."] = "الإبقاء على الداخل: تُقص العناصر التي تقطع الحدود فقط. لا يُمس ما هو خارجها.",
            ["Keep outside: objects inside are removed, crossing ones are cut. The boundary itself is not changed. One UNDO."] = "الإبقاء على الخارج: تُحذف العناصر الداخلية وتُقص المتقاطعة. لا تتغير الحدود نفسها. أمر UNDO واحد.",
            ["Pick the closed polyline to use as the boundary: "] = "حدّد الخط المتعدد المغلق ليكون الحدود: ",["Only a polyline can be the boundary."] = "لا يصلح حدودًا إلا الخط المتعدد.",
            ["Select objects to trim (Enter = only the objects crossing or inside the polygon's area)"] = "حدّد العناصر المراد قصها (Enter = العناصر المتقاطعة أو الواقعة داخل المضلع فقط)",
            // measure
            ["Start point of the line to measure: "] = "نقطة بداية الخط المراد قياسه: ",["Total length (horizontal)"] = "الطول الكلي (أفقي)",["Total length (slope, with Z)"] = "الطول الكلي (مائل، مع Z)",["Segments (m)"] = "القطع (م)",
            ["Writing in the drawing adds a polyline and the total on layer BP-MEASURE."] = "الكتابة في الرسم تضيف خطًا متعددًا والمجموع على الطبقة BP-MEASURE.",["First corner of the area: "] = "أول زاوية في المنطقة: ",
            ["Warning: the outline crosses itself, so the area is not what you expect."] = "تحذير: الحدود تتقاطع مع نفسها، فالمساحة ليست كما تتوقع.",
            ["Writing in the drawing adds a closed polyline and the area on layer BP-MEASURE."] = "الكتابة في الرسم تضيف خطًا متعددًا مغلقًا والمساحة على الطبقة BP-MEASURE.",
            ["First point (end of the first line): "] = "النقطة الأولى (نهاية الخط الأول): ",["Corner point (where the angle is): "] = "نقطة الزاوية (موضع الزاوية): ",["Last point (end of the second line): "] = "النقطة الأخيرة (نهاية الخط الثاني): ",
            ["Writing in the drawing adds the angle as text at the corner (layer BP-MEASURE)."] = "الكتابة في الرسم تضيف الزاوية نصًا عند الرأس (الطبقة BP-MEASURE).",["Pick a point: "] = "حدّد نقطة: ",
            ["No coordinate system is set for this drawing, so no latitude and longitude. Set one with BPGMAPCS."] = "لم يُضبط نظام إحداثيات لهذا الرسم، فلا يوجد خط عرض ولا خط طول. اضبط نظامًا بالأمر BPGMAPCS.",
            // ---- batch 3: plot, app, sinks, formats, map dialog, engine, assemblies
            ["My settings (same for all ticked)"] = "إعداداتي (نفسها لكل اللوحات المعلّمة)",["Scale (Fit or 1:500)"] = "المقياس (Fit أو 1:500)",
            ["Fit plots the sheet at 1:1. A scale like 1:500 means 1 mm on paper = 500 mm of drawing."] = "الخيار Fit يطبع اللوحة بمقياس 1:1. المقياس 1:500 يعني أن 1 مم على الورق = 500 مم من الرسم.",
            ["Arabic text found. On this AutoCAD version DWG To PDF can print Arabic letters separated. Try Microsoft Print to PDF."] = "وُجد نص عربي. في هذا الإصدار من أوتوكاد قد يطبع DWG To PDF الحروف العربية منفصلة. جرّب Microsoft Print to PDF.",
            ["Arabic text found: Microsoft Print to PDF chosen so the letters stay joined."] = "وُجد نص عربي: اختير Microsoft Print to PDF لتبقى الحروف متصلة.",
            ["Printer (as chosen above)"] = "الطابعة (كما اخترتها أعلاه)",
            ["Microsoft Print to PDF: Windows may ask where to save each file. Choose the folder and click Save. One PDF per layout. It stops after 2 minutes."] = "Microsoft Print to PDF: قد يسألك ويندوز أين يحفظ كل ملف. اختر المجلد وانقر حفظ. ملف PDF واحد لكل لوحة. يتوقف بعد دقيقتين.",
            ["Tick at least one layout."] = "علّم لوحة واحدة على الأقل.",["Choose a folder for the PDF files."] = "اختر مجلدًا لملفات PDF.",["Choose a paper size for this printer first."] = "اختر حجم ورق لهذه الطابعة أولًا.",
            ["No printer or PDF device is available for this choice."] = "لا توجد طابعة أو جهاز PDF متاح لهذا الاختيار.",["Scale: type Fit or something like 1:500."] = "المقياس: اكتب Fit أو شيئًا مثل 1:500.",
            ["B+ CAD Tools - Plot layouts"] = "B+ CAD Tools - طباعة اللوحات",["LAYOUTS"] = "اللوحات",["PAGE"] = "الصفحة",["SAVE AS"] = "الحفظ",["All"] = "الكل",
            ["Each layout's own page setup"] = "إعداد الصفحة الخاص بكل لوحة",["Printer / PDF"] = "الطابعة / PDF",["Paper size"] = "حجم الورق",["Plot style"] = "نمط الطباعة",["Drawing on paper"] = "الرسم على الورق",
            ["As in the layout"] = "كما في اللوحة",["Plot line weights"] = "طباعة سماكات الخطوط",["Fit"] = "ملاءمة",
            ["This drawing has unsaved changes.\r\n\r\nPlotting talks to the printer drivers, and a driver problem can close AutoCAD without warning.\r\nSave the drawing first?"] = "في هذا الرسم تغييرات غير محفوظة.\r\n\r\nتتعامل الطباعة مع برامج تشغيل الطابعات، وقد تُغلق مشكلة في أحدها أوتوكاد دون إنذار.\r\nهل تحفظ الرسم أولًا؟",
            // app
            ["No Google key is saved. Click Live map > Options > Settings and Google key, paste your key, tick the terms and press Save."] = "لا يوجد مفتاح Google محفوظ. انقر الخريطة الحية > خيارات > الإعدادات ومفتاح Google، والصق مفتاحك، وعلّم الشروط، ثم اضغط حفظ.",
            ["Map opacity percent (10-100)"] = "نسبة شفافية الخريطة (10-100)",
            ["Word to look for in the coordinate library (e.g. GRF17, Saudi, UTM; Enter = everything): "] = "كلمة للبحث عنها في مكتبة الإحداثيات (مثل GRF17 أو Saudi أو UTM؛ Enter = الكل): ",
            // sinks
            ["Sampling the surface: "] = "جارٍ أخذ عينات من السطح: ",["Cancelled (Esc)."] = "أُلغي (Esc).",["Stopped after 90 seconds: reading this surface is too slow. Use a larger grid cell."] = "توقف بعد 90 ثانية: قراءة هذا السطح بطيئة جدًا. استخدم خلية شبكة أكبر.",
            ["The surface gave an elevation at fewer than 5% of the sampled places. Check the surface or use a larger grid cell."] = "أعطى السطح منسوبًا في أقل من 5% من المواضع المأخوذة. تحقق من السطح أو استخدم خلية شبكة أكبر.",
            ["No elevation could be read from the surface (empty, or outside its border)."] = "تعذّرت قراءة أي منسوب من السطح (فارغ أو خارج حدوده).",
            ["Civil 3D surface read through its elevation method (not tested on a real surface: check a few values)."] = "قُرئ سطح Civil 3D عبر دالة المناسيب فيه (لم تُجرَّب على سطح حقيقي: تحقق من بعض القيم).",
            // format picker
            ["After you choose, the file opens in the import window (columns, codes, layers)."] = "بعد الاختيار يُفتح الملف في نافذة الاستيراد (الأعمدة والأكواد والطبقات).",["Next: the usual export options (order, categories, file name)."] = "بعد ذلك: خيارات التصدير المعتادة (الترتيب والفئات واسم الملف).",
            ["Unverified = written from the format spec, not yet tested with a real instrument file."] = "غير موثّق = كُتب من مواصفات الصيغة ولم يُجرَّب بعد بملف حقيقي من الجهاز.",
            // map settings dialog
            ["Use the BPlus map server (no key needed, shared monthly limit)"] = "استخدام خادم خرائط BPlus (لا يحتاج مفتاحًا، بحد شهري مشترك)",["BPlus map server: not available yet (use your own key)"] = "خادم خرائط BPlus: غير متاح بعد (استخدم مفتاحك الخاص)",
            ["Use my own Google Maps Platform key (my own Google account and cost)"] = "استخدام مفتاحي الخاص في Google Maps Platform (حسابي وتكلفتي)",["Your Google key (only for 'my own key')"] = "مفتاح Google الخاص بك (لخيار \"مفتاحي الخاص\" فقط)",
            ["No key saved yet. Paste it here. It stays on this PC only."] = "لا يوجد مفتاح محفوظ بعد. الصقه هنا. يبقى على هذا الجهاز فقط.",["Hybrid (satellite + labels)"] = "هجين (أقمار صناعية + أسماء)",["Warn me at (requests)"] = "نبّهني عند (عدد الطلبات)",
