        /// <summary>Arabic for an English UI string. Keeps a leading line break and the [B+] tag of command-line messages.</summary>
        public static string T(string en)
        {
            if (!On || string.IsNullOrEmpty(en)) return en; string v;
            if (D.TryGetValue(en, out v)) return v;
            int i = 0; while (i < en.Length && (en[i] == '\n' || en[i] == '\r')) i++;
            string pre = en.Substring(0, i), rest = en.Substring(i); if (rest.StartsWith("[B+] ")) { pre += "[B+] "; rest = rest.Substring(5); } else if (rest.StartsWith("[BPlus] ")) { pre += "[BPlus] "; rest = rest.Substring(8); } else if (rest.StartsWith("[BPlus map] ")) { pre += "[BPlus map] "; rest = rest.Substring(12); }
            int j = rest.Length; while (j > 0 && (rest[j - 1] == '\n' || rest[j - 1] == '\r')) j--;
            string core = rest.Substring(0, j), post = rest.Substring(j);
            if ((pre.Length > 0 || post.Length > 0) && D.TryGetValue(core, out v)) return pre + v + post;
            return en;
        }

        /// <summary>Translates a whole dialog: titles, labels, buttons, tick boxes, radio buttons, list columns, drop-down items; labels that get their text later (messages) are translated when they change.</summary>
        public static void Form(System.Windows.Forms.Form f)
        {
            if (!On || f == null) return; f.Text = T(f.Text); Walk(f);
        }
        static void Walk(Control c)
        {
            foreach (Control k in c.Controls)
            {
                if (k is Label || k is Button || k is CheckBox || k is RadioButton || k is GroupBox) { k.Text = T(k.Text); var lb = k as Label; if (lb != null) { bool busy = false; lb.TextChanged += (s, e) => { if (busy) return; busy = true; try { lb.Text = T(lb.Text); } finally { busy = false; } }; } }
                var cb = k as ComboBox; if (cb != null && cb.DropDownStyle == ComboBoxStyle.DropDownList) for (int i = 0; i < cb.Items.Count; i++) { var s0 = cb.Items[i] as string; if (s0 != null) { string t = T(s0); if (t != s0) { int sel = cb.SelectedIndex; cb.Items[i] = t; cb.SelectedIndex = sel; } } }
                var lv = k as ListView; if (lv != null) foreach (ColumnHeader h in lv.Columns) h.Text = T(h.Text);
                Walk(k);
            }
        }
    }
